class Solution {
    fun removeStars(s: String): String {
        val stack = ArrayDeque<Char>()

        for (i in s.indices){
            if(s[i] != '*'){
                stack.addLast(s[i])
            } else if(s[i] == '*'){
                stack.removeLast()
            }
        }

        return stack.joinToString("")


    }
}

class Solution {
public:
    long long minCuttingCost(int n, int m, int k) {
        long long cost=0;
        if(k>=n && k>=m){
            return 0;
        }
        if(n>k){
            cost += 1LL*(n-k)*(k);            
        }
        if(m>k){
             cost += 1LL*(m-k)*(k);            
        }

        return cost;
    }
};

